479	// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
480	// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
481	// when agentType is known, falling back to JSONL reassembly otherwise.
482	func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
483		var chunkFiles []string
484		var hasBaseFile bool
485	
486		for _, entry := range tree.Entries {
487			if entry.Name == paths.V2RawTranscriptFileName {
488				hasBaseFile = true
489			}
490			if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
491				idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
492				if idx > 0 {
493					chunkFiles = append(chunkFiles, entry.Name)
494				}
495			}
496		}
497	
498		// If chunk files exist, reassemble all chunks (base file is chunk 0)
499		if len(chunkFiles) > 0 {
500			chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
501			if hasBaseFile {
502				chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
503			}
504	
505			var chunks [][]byte
506			for _, chunkFile := range chunkFiles {
507				file, fileErr := tree.File(chunkFile)
508				if fileErr != nil {
509					continue
510				}
511				content, contentErr := file.Contents()
512				if contentErr != nil {
513					continue
514				}
515				chunks = append(chunks, []byte(content))
516			}
517	
518			if len(chunks) > 0 {
519				result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
520				if reassembleErr != nil {
521					return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
522				}
523				return result, nil
524			}
525		}
526	
527		// No chunk files — read base file directly (non-chunked transcript)
528		if hasBaseFile {
529			file, err := tree.File(paths.V2RawTranscriptFileName)
530			if err == nil {
531				content, contentErr := file.Contents()
532				if contentErr == nil {
533					return []byte(content), nil
534				}
535			}
536		}
537	
538		return nil, nil
539	}
