93	func repairOneV2GenerationMetadata(
94		ctx context.Context,
95		repo *git.Repository,
96		store *checkpoint.V2GitStore,
97		candidate archivedV2GenerationCandidate,
98		pushTarget *repairPushTarget,
99	) (bool, error) {
100		oldCommitHash, treeHash, refErr := store.GetRefState(candidate.RefName)
101		if refErr != nil {
102			return false, fmt.Errorf("cannot read ref: %w", refErr)
103		}
104	
105		gen, found, timestampErr := store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
106		if timestampErr != nil {
107			return false, fmt.Errorf("failed to compute raw transcript timestamps: %w", timestampErr)
108		}
109		if !found {
110			gen, found, timestampErr = store.ComputeGenerationCheckpointTimestamps(treeHash)
111			if timestampErr != nil {
112				return false, fmt.Errorf("failed to compute checkpoint timestamps: %w", timestampErr)
113			}
114			if !found {
115				return false, nil
116			}
117		}
118	
119		current, genErr := store.ReadGeneration(treeHash)
120		if genErr != nil {
121			return false, fmt.Errorf("failed to read generation.json: %w", genErr)
122		}
123		if generationMetadataEqual(current, gen) {
124			return false, nil
125		}
126	
127		newTreeHash, addErr := store.AddGenerationJSONToTree(treeHash, gen)
128		if addErr != nil {
129			return false, fmt.Errorf("failed to rewrite generation.json: %w", addErr)
130		}
131		if newTreeHash == treeHash {
132			return false, nil
133		}
134	
135		newCommitHash, commitErr := checkpoint.CreateCommit(ctx, repo, newTreeHash, oldCommitHash,
136			fmt.Sprintf("Repair generation metadata: %s\n", candidate.Name),
137			repairAuthorName, repairAuthorEmail)
138		if commitErr != nil {
139			return false, fmt.Errorf("failed to create repair commit: %w", commitErr)
140		}
141	
142		if err := repo.Storer.SetReference(plumbing.NewHashReference(candidate.RefName, newCommitHash)); err != nil {
143			return false, fmt.Errorf("failed to update ref %s: %w", candidate.RefName, err)
144		}
145	
146		if !candidate.HasRemote {
147			return true, nil
148		}
149	
150		target, err := pushTarget.resolve(ctx)
151		if err != nil {
152			rollbackRepairLocalRef(repo, candidate.RefName, oldCommitHash)
153			return false, fmt.Errorf("failed to resolve remote for generation metadata repair push: %w", err)
154		}
155		if target == "" {
156			rollbackRepairLocalRef(repo, candidate.RefName, oldCommitHash)
157			return false, errors.New("no push target available for remote generation metadata repair")
158		}
159	
160		remoteRefName := paths.V2FullRefPrefix + candidate.Name
161		if err := pushRepairedV2Generation(ctx, target, candidate.RefName.String(), remoteRefName, candidate.RefOID); err != nil {
162			rollbackRepairLocalRef(repo, candidate.RefName, oldCommitHash)
163			return false, err
164		}
165		return true, nil
166	}
