168	// rollbackRepairLocalRef restores the local ref to its pre-repair commit when
169	// the remote push fails, so local does not silently diverge from origin.
170	func rollbackRepairLocalRef(repo *git.Repository, refName plumbing.ReferenceName, oldCommitHash plumbing.Hash) {
171		_ = repo.Storer.SetReference(plumbing.NewHashReference(refName, oldCommitHash)) //nolint:errcheck // best-effort rollback; the original push error is what we report
172	}
