174	// repairPushTarget memoizes the push URL lookup so the remote is resolved at
175	// most once, only when a candidate actually needs to push.
176	type repairPushTarget struct {
177		resolved bool
178		target   string
179		err      error
180	}
181	
182	func (r *repairPushTarget) resolve(ctx context.Context) (string, error) {
183		if r.resolved {
184			return r.target, r.err
185		}
186		r.resolved = true
187		target, _, err := remote.PushURL(ctx, "origin")
188		if err != nil {
189			r.err = fmt.Errorf("push URL: %w", err)
190			return "", r.err
191		}
192		r.target = target
193		return target, nil
194	}
