196	func pushRepairedV2Generation(ctx context.Context, target, sourceRef, remoteRef, expectedOID string) error {
197		return pushWithLease(ctx, target, sourceRef+":"+remoteRef, remoteRef, expectedOID,
198			"push repaired generation ref "+remoteRef)
199	}
