117	func publishPendingV2FullGenerationPublications(
118		ctx context.Context,
119		repo *git.Repository,
120		store *checkpoint.V2GitStore,
121		target string,
122		publications []checkpoint.PendingV2FullGenerationPublication,
123	) (pendingV2FullGenerationPublicationResult, error) {
124		var result pendingV2FullGenerationPublicationResult
125		if len(publications) == 0 {
126			return result, nil
127		}
128	
129		currentRefName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
130		var localCurrentRef *plumbing.Reference
131		for {
132			latestResetPublicationIndex := latestPendingFullCurrentResetPublicationIndex(publications)
133			if latestResetPublicationIndex == -1 {
134				break
135			}
136			var err error
137			localCurrentRef, err = repo.Reference(currentRefName, true)
138			if err != nil {
139				return result, fmt.Errorf("read local %s: %w", shortRefName(currentRefName), err)
140			}
141			latestResetPublication := publications[latestResetPublicationIndex]
142			if pendingResetPublicationMatchesLocalCurrent(ctx, repo, latestResetPublication, localCurrentRef.Hash()) {
143				break
144			}
145			if err := store.RemovePendingFullGenerationPublications(ctx, []checkpoint.PendingV2FullGenerationPublication{latestResetPublication}); err != nil {
146				return result, fmt.Errorf("clear stale pending v2 full generation publications: %w", err)
147			}
148			publications = slices.Delete(publications, latestResetPublicationIndex, latestResetPublicationIndex+1)
149		}
150	
151		archiveRefs := pendingFullArchiveRefs(publications)
152		if len(archiveRefs) > 0 {
153			var archivePushErr error
154			for _, pushResult := range tryPushV2Refs(ctx, target, archiveRefs) {
155				if pushResult.err != nil {
156					if archivePushErr == nil {
157						archivePushErr = fmt.Errorf("push pending archive %s: %w", shortRefName(pushResult.refName), pushResult.err)
158					}
159					continue
160				}
161				result.successfulRefs = append(result.successfulRefs, pushResult.refName)
162			}
163			if archivePushErr != nil {
164				return result, archivePushErr
165			}
166		}
167	
168		resetPublications := pendingFullCurrentResetPublications(publications)
169		if len(resetPublications) == 0 {
170			if err := store.RemovePendingFullGenerationPublications(ctx, publications); err != nil {
171				return result, fmt.Errorf("clear pending v2 full generation publications: %w", err)
172			}
173			return result, nil
174		}
175	
176		remoteCurrentHash, remoteCurrentFound, err := lsRemoteRefHash(ctx, target, currentRefName)
177		if err != nil {
178			return result, fmt.Errorf("read remote %s: %w", shortRefName(currentRefName), err)
179		}
180		if remoteCurrentFound && remoteCurrentHash == localCurrentRef.Hash() {
181			if err := store.RemovePendingFullGenerationPublications(ctx, publications); err != nil {
182				return result, fmt.Errorf("clear pending v2 full generation publications: %w", err)
183			}
184			result.fullCurrentResetHandled = true
185			return result, nil
186		}
187	
188		if remoteCurrentFound && !pendingResetPublicationsContainAncestor(ctx, repo, resetPublications, remoteCurrentHash) {
189			return result, fmt.Errorf("remote %s at %s is not covered by pending local archives", shortRefName(currentRefName), remoteCurrentHash)
190		}
191	
192		expectedRemoteHash := ""
193		if remoteCurrentFound {
194			expectedRemoteHash = remoteCurrentHash.String()
195		}
196		currentRefSpec := fmt.Sprintf("%s:%s", currentRefName, currentRefName)
197		if err := pushWithLease(ctx, target, currentRefSpec, currentRefName.String(), expectedRemoteHash, "push rotated "+shortRefName(currentRefName)); err != nil {
198			return result, fmt.Errorf("push rotated %s: %w", shortRefName(currentRefName), err)
199		}
200		result.successfulRefs = append(result.successfulRefs, currentRefName)
201		result.fullCurrentResetHandled = true
202	
203		if err := store.RemovePendingFullGenerationPublications(ctx, publications); err != nil {
204			return result, fmt.Errorf("clear pending v2 full generation publications: %w", err)
205		}
206		return result, nil
207	}
